package dev.starfold;

import net.minecraft.core.*;
import net.minecraft.core.registries.BuiltInRegistries;
import net.minecraft.resources.ResourceLocation;
import net.minecraft.world.level.block.EntityBlock;
import net.minecraft.world.level.block.state.properties.BlockStateProperties;
import org.junit.jupiter.api.Test;
import java.nio.file.*;
import static org.junit.jupiter.api.Assertions.*;

class NativeHelmBlockTest {
    @org.junit.jupiter.api.BeforeAll static void boot(){NativePlanetEcologyTest.boot();}
    @Test void fourDirectionsAndEntityAreRegistered(){var id=ResourceLocation.parse("starfold:helm");var block=BuiltInRegistries.BLOCK.get(id);assertInstanceOf(NativeThruster.HelmBlock.class,block);assertEquals(id,BuiltInRegistries.ITEM.getKey(block.asItem()));for(var d:new Direction[]{Direction.NORTH,Direction.SOUTH,Direction.WEST,Direction.EAST}){var state=block.defaultBlockState().setValue(BlockStateProperties.HORIZONTAL_FACING,d);var entity=((EntityBlock)block).newBlockEntity(BlockPos.ZERO,state);assertInstanceOf(NativeThruster.Helm.class,entity);assertEquals(id,BuiltInRegistries.BLOCK_ENTITY_TYPE.getKey(entity.getType()));assertNull(((EntityBlock)block).getTicker(null,state,entity.getType()));}}
    @Test void resourcesHaveFourModelsVanillaRecipeLootAndTools()throws Exception{var variants=NativeFlightPermitTest.json("assets/starfold/blockstates/helm.json").getAsJsonObject("variants");assertEquals(4,variants.size());assertEquals(3,NativeFlightPermitTest.json("assets/starfold/models/block/helm.json").getAsJsonArray("elements").size());assertEquals("starfold:block/helm",NativeFlightPermitTest.json("assets/starfold/models/item/helm.json").get("parent").getAsString());var recipe=NativeFlightPermitTest.json("data/starfold/recipe/helm.json");for(var e:recipe.getAsJsonObject("key").entrySet())assertTrue(e.getValue().getAsJsonObject().get("item").getAsString().startsWith("minecraft:"));assertTrue(NativeFlightPermitTest.json("data/starfold/loot_table/blocks/helm.json").toString().contains("starfold:helm"));for(var tag:new String[]{"mineable/pickaxe","needs_iron_tool"})assertTrue(NativeFlightPermitTest.json("data/minecraft/tags/block/"+tag+".json").toString().contains("starfold:helm"));for(var lang:new String[]{"en_us","zh_cn"})assertNotNull(NativeFlightPermitTest.json("assets/starfold/lang/"+lang+".json").get("block.starfold.helm"));for(var name:new String[]{"helm_housing","helm_screen","helm_arrow"}){var image=javax.imageio.ImageIO.read(Path.of("src/main/resources/assets/starfold/textures/block/"+name+".png").toFile());assertEquals(16,image.getWidth());assertEquals(16,image.getHeight());assertNotEquals(image.getRGB(0,0),image.getRGB(7,7));}}
    @Test void serverAndClientShareSelectorAndDoNotSavePilotOrWritePowerStates()throws Exception{String base="src/main/java/dev/starfold/";var server=Files.readString(Path.of(base+"NativeHelmServer.java"));var client=Files.readString(Path.of(base+"NativeHelmInputClient.java"));assertTrue(server.contains("NativeHelmCommand.fires"));assertTrue(client.contains("NativeHelmCommand.fires"));assertFalse(server.contains("setBlock("));assertFalse(server.contains("saveAdditional"));assertFalse(server.contains("Class.forName"));assertTrue(client.contains("MovementInputUpdateEvent"));for(var key:new String[]{"keyUp","keyDown","keyLeft","keyRight","keyJump","keyShift","keySprint"})assertTrue(client.contains(key+".isDown()"));assertTrue(Files.readString(Path.of(base+"NativeThruster.java")).contains("event.accept(helm)"));assertFalse(Files.exists(Path.of(base+"mixin/NativeHelmUserMixin.java")));}
}
